920	    /**
921	     * The declared domains of an own generic function f (o1) and an own
922	     * generic function or a declaration without static parameters g (o2),
923	     * each over its own static parameters (Apart), exclude each other read
924	     * whole, by existential reduction: a value of both has, at each position,
925	     * one instance of each generic type that the two parameter types there
926	     * both are or extend (no type extends two instances of one generic type),
927	     * so their static arguments are equal (matchApart).  The domains exclude
928	     * where two such instances cannot be equal (argsMayBeEqual), where the
929	     * equalities of every position together make one static parameter two
930	     * types that cannot be equal, or where, each class of static parameters
931	     * so made equal read as one (meetParams), the two parameter types at some
932	     * position exclude at every instance of the static parameters they still
933	     * mention (excludesAtMeet).  Static arguments that may be equal but do not
934	     * match so are left apart, which shows less.
935	     */
936	    static private boolean domainsExcludeTogether(Overload o1, Overload o2) {
937	        if (!(o1.getFn() instanceof FGenericFunction)) return false;
938	        FGenericFunction f = (FGenericFunction) o1.getFn();
939	        boolean plain = !(o2.getFn() instanceof GenericFunctionOrMethod);
940	        if (!plain && !(o2.getFn() instanceof FGenericFunction)) return false;
941	        /* A declaration without static parameters is read as g with none, f standing for it in meetParams. */
942	        FGenericFunction g = plain ? f : (FGenericFunction) o2.getFn();
943	        if (NodeUtil.getWhereClause(f.getFnDecl()).isSome() || NodeUtil.getWhereClause(g.getFnDecl()).isSome()) {
944	            return false;
945	        }
946	        try {
947	            Apart apart = plain ? null : Apart.of(o1, o2);
948	            List<FType> fArgs = GenericFunctionOrMethod.FunctionsAndState.symbolicStaticsByPartition.get(f);
949	            List<FType> gArgs = plain ? Collections.<FType>emptyList() : apart.fresh != null ? apart.fresh :
950	                                GenericFunctionOrMethod.FunctionsAndState.symbolicStaticsByPartition.get(g);
951	            List<FType> d1 = o1.getParams();
952	            List<FType> d2 = plain ? o2.getParams() : apart.domain;
953	            if (fArgs == null || gArgs == null || d1.size() != d2.size() || hasRest(d1) || hasRest(d2)) return false;
954	            if (fArgs.size() != f.getStaticParams().size() || !plain && gArgs.size() != g.getStaticParams().size()) {
955	                return false;
956	            }
957	            Map<FType, FType> parent = new IdentityHashMap<FType, FType>();
958	            for (int k = 0; k < d1.size(); k++) {
959	                for (FType t1 : withSupertypes(d1.get(k))) {
960	                    if (!(t1 instanceof GenericTypeInstance)) continue;
961	                    for (FType t2 : withSupertypes(d2.get(k))) {
962	                        if (!(t2 instanceof GenericTypeInstance) || !sameGeneric(t1, t2)) continue;
963	                        if (!argsMayBeEqual(((GenericTypeInstance) t1).getTypeParams(),
964	                                            ((GenericTypeInstance) t2).getTypeParams())) return true;
965	                        Map<FType, FType> tried = new IdentityHashMap<FType, FType>(parent);
966	                        if (matchApart(t1, t2, tried)) parent = tried;
967	                    }
968	                }
969	            }
970	            Map<FType, List<FType>> classes = new IdentityHashMap<FType, List<FType>>();
971	            for (FType t : new ArrayList<FType>(parent.keySet())) {
972	                FType r = root(t, parent);
973	                List<FType> c = classes.get(r);
974	                if (c == null) classes.put(r, c = new ArrayList<FType>());
975	                c.add(t);
976	            }
977	            Set<FType> params = Collections.newSetFromMap(new IdentityHashMap<FType, Boolean>());
978	            params.addAll(fArgs);
979	            params.addAll(gArgs);
980	            for (List<FType> c : classes.values()) {
981	                FType one = null;
982	                for (FType t : c) {
983	                    if (params.contains(t)) continue;
984	                    if (one == null) one = t;
985	                    else if (!mayBeEqual(one, t)) return true;
986	                    else if (!one.equals(t)) return false;
987	                }
